package versioninfo

import "fmt"

// Version and Commit are set at build time via ldflags.
var (
	Version = "dev"
	Commit  = "unknown"
)

// FormatVersion renders the version string for checkpoint provenance.
// Releases and nightlies already encode everything in version, so they pass
// through verbatim (e.g. "v0.0.1", "v0.5.1-nightly..."). Local "dev" builds
// carry no version detail, so the commit digest is appended: "dev (abc1234)".
func FormatVersion(version, commit string) string {
	if version == "dev" && commit != "" && commit != "unknown" {
		return fmt.Sprintf("dev (%s)", commit)
	}
	return version
}

// CheckpointVersion returns the formatted current build version, used to stamp
// the Entire-Version trailer on committed checkpoints.
func CheckpointVersion() string {
	return FormatVersion(Version, Commit)
}
